const byId=new Map(definitions.map(d=>[d.id,d]));
export class ActionError extends Error{constructor(code,message){super(message);this.code=code;this.name='ActionError';}}
export function actionContract(id){const a=byId.get(id);if(!a)throw new ActionError('UNKNOWN_ACTION','등록된 실행을 확인하세요.');const{handler,...contract}=a;return structuredClone(contract);}
export function dispatchAction(id,input={},context={}){
 const a=byId.get(id);if(!a)throw new ActionError('UNKNOWN_ACTION','등록된 실행을 확인하세요.');
 if(a.policy==='FORBIDDEN'||a.status==='planned')throw new ActionError('ACTION_FORBIDDEN','준비 중인 실행입니다.');
 if(!a.handler)throw new ActionError('SERVER_ACTION_REQUIRED','서버에서 실행할 항목입니다.');
 if(context.mode!=='paper'||!a.surfaces.includes(context.surface)||!a.actors.includes(context.actor)||!a.runtime.includes(context.runtime))throw new ActionError('ACTION_NOT_ALLOWED','이 환경의 실행 권한을 확인하세요.');
 if(context.allowedActions&&(!Array.isArray(context.allowedActions)||!context.allowedActions.includes(id)))throw new ActionError('CAPABILITY_NOT_ALLOWED','허용된 실행 범위를 확인하세요.');
 if(!input||typeof input!=='object'||Array.isArray(input)||!a.inputs.every(k=>Object.hasOwn(input,k))||Object.keys(input).some(k=>!a.inputs.includes(k)&&!(a.optional_inputs||[]).includes(k)))throw new ActionError('INVALID_ACTION_INPUT','실행 입력 항목을 확인하세요.');
 return a.handler(input);
}
